export function addInfluence(project,kind='attractor'){if(!project.working.weave)throw Error('Create an Influenced Grid first.');if(!['attractor','repeller','deflector'].includes(kind))throw Error('Choose a supported influence type.');const draft=copyProjectForEdit(project),w=draft.working.weave;promoteCombined(w,draft.working.carrier);if(w.generation.influences.length>=COMBINED_LIMITS.influences)throw Error('Use no more than eight influences.');w.generation.influences.push(newInfluence(draft.working.boundary,draft.working.carrier,kind));validateFieldGeneration(w.generation);return draft;}
export function duplicateInfluence(project,influenceId){const draft=copyProjectForEdit(project),w=draft.working.weave;promoteCombined(w,draft.working.carrier);const source=influenceOf(w,influenceId);if(!source)throw Error('Choose an influence to duplicate.');if(w.generation.influences.length>=COMBINED_LIMITS.influences)throw Error('Use no more than eight influences.');w.generation.influences.push(newInfluence(draft.working.boundary,draft.working.carrier,source.kind,source));validateFieldGeneration(w.generation);return draft;}
export function candidateInfluence(project,changes){const draft=copyProjectForEdit(project),w=draft.working.weave;if(!influenceOf(w))throw Error('Add an influence first.');promoteCombined(w,draft.working.carrier);const g=w.generation,field=influenceOf(w,changes.influenceId);if(!field)throw Error('Choose an active influence.');if(changes.familySettings){if(!field.families[changes.family])throw Error('Choose an available family.');field.families[changes.family]={...field.families[changes.family],...changes.familySettings};}if(changes.families)for(const [name,value] of Object.entries(changes.families))if(field.families[name])field.families[name]={...field.families[name],...value};if('influence'in changes)Object.assign(field,{...changes.influence,center:changes.influence.center?{...changes.influence.center}:{...field.center}});validateFieldGeneration(g);return draft;}
export function candidateVariation(project,changes){const draft=copyProjectForEdit(project),w=draft.working.weave;promoteCombined(w,draft.working.carrier);const v=w.generation.variation;if('seed'in changes)v.seed=changes.seed;if(changes.family&&changes.amount!==undefined){if(!v.families[changes.family])throw Error('Choose an available family.');v.families[changes.family].amount=changes.amount;}if(changes.families)for(const [name,value] of Object.entries(changes.families))if(v.families[name])v.families[name]={...v.families[name],...value};validateFieldGeneration(w.generation);return draft;}
export function removeInfluence(project,influenceId=null){const draft=clone(project),w=draft.working.weave;if(!influenceOf(w,influenceId))throw Error('Choose an influence first.');promoteCombined(w,draft.working.carrier);const target=influenceId||w.generation.influences[0].id;w.generation.influences=w.generation.influences.filter(f=>f.id!==target);validateFieldGeneration(w.generation);draft.working=refreshWeave(draft.working,draft.id);return draft;}

export function addWeaveFamily(project,copyFamily=null){const draft=clone(project);if(!draft.working.carrier)throw Error('Create a Weave Pattern first.');const carrier=draft.working.carrier;if(carrier.generatorVersion==='rect-v1'){const base=carrier.angleDegrees;carrier.generatorVersion='rect-v2';carrier.families.A.angleDegrees=base;carrier.families.B.angleDegrees=Math.max(-180,Math.min(180,base+90));delete carrier.angleDegrees;}const name=nextFamilyName(carrier),source=copyFamily&&carrier.families[copyFamily];carrier.families[name]=source?{...clone(source),angleDegrees:Math.max(-180,Math.min(180,source.angleDegrees+30))}:{angleDegrees:(familyNames(carrier).length*180/(familyNames(carrier).length+1)),spacing:50,offset:0,density:100};draft.working.familyCatalog=addCatalogFamily(carrier,draft.working.familyCatalog,name,copyFamily);validateCarrierRecipe(carrier);if(draft.working.weave)promoteCombined(draft.working.weave,carrier);draft.working.carrierSourceRevisionId=null;return{project:draft,family:name};}
export function removeWeaveFamily(project,family){const draft=clone(project),carrier=draft.working.carrier;if(!carrier?.families[family])throw Error('Choose a family to remove.');if(familyNames(carrier).length<=2)throw Error('A Weave Pattern needs at least two families.');delete carrier.families[family];carrier.generatorVersion='rect-v2';delete carrier.angleDegrees;draft.working.familyCatalog=removeCatalogFamily(carrier,draft.working.familyCatalog,family);if(draft.working.threadAppearance?.families)delete draft.working.threadAppearance.families[family];if(draft.working.interlacing){const remaining=familyNames(carrier);if(draft.working.interlacing.topFamily===family)draft.working.interlacing.topFamily=remaining[0];if(draft.working.interlacing.rule?.pairs)draft.working.interlacing.rule.pairs=draft.working.interlacing.rule.pairs.filter(pair=>pair.first!==family&&pair.second!==family);}validateCarrierRecipe(carrier);if(draft.working.weave)promoteCombined(draft.working.weave,carrier);draft.working.carrierSourceRevisionId=null;return draft;}

function uniqueName(items,base){let name=cleanName(base+' COPY'),n=2;while(items.some(x=>x.name===name))name=cleanName(base+` COPY ${n++}`);return name;}
export function renameLibraryItem(project,type,itemId,name){const draft=clone(project),key=type==='boundary'?'boundaries':type==='pattern'?'carrierStudies':'weaveStudies',items=draft[key],item=items.find(x=>x.id===itemId),clean=cleanName(name);if(!item||!clean)throw Error('Choose an item and provide a name.');if(items.some(x=>x.id!==itemId&&x.name===clean))throw Error('That name is already used here.');item.name=clean;return draft;}
export function deleteLibraryItem(project,type,itemId){const draft=clone(project);if(type==='influenced'){const entry=draft.weaveStudies.find(x=>x.id===itemId);if(!entry)throw Error('Influenced Grid is missing.');draft.weaveStudies=draft.weaveStudies.filter(x=>x.id!==itemId);if(draft.working.weave?.studyId===itemId)draft.working.weave=null;return draft;}if(type==='pattern'){const entry=draft.carrierStudies.find(x=>x.id===itemId);if(!entry)throw Error('Weave Pattern is missing.');const revisions=new Set(entry.revisions.map(r=>r.id));draft.weaveStudies=draft.weaveStudies.filter(x=>!revisions.has(x.revisions[0]?.working?.weave?.sourceContext?.sourceCarrierRevisionId));draft.carrierStudies=draft.carrierStudies.filter(x=>x.id!==itemId);if(revisions.has(draft.working.carrierSourceRevisionId)){draft.working={...draft.working,carrier:null,carrierSourceRevisionId:null,weave:null};delete draft.working.familyCatalog;delete draft.working.threadAppearance;delete draft.working.interlacing;}return draft;}const entry=draft.boundaries.find(x=>x.id===itemId);if(!entry)throw Error('Boundary is missing.');const boundaries=new Set(entry.revisions.map(r=>r.id)),patterns=draft.carrierStudies.filter(x=>x.revisions.some(r=>boundaries.has(r.boundarySourceRevisionId))),patternRevisions=new Set(patterns.flatMap(x=>x.revisions.map(r=>r.id)));draft.weaveStudies=draft.weaveStudies.filter(x=>!patternRevisions.has(x.revisions[0]?.working?.weave?.sourceContext?.sourceCarrierRevisionId));draft.carrierStudies=draft.carrierStudies.filter(x=>!patterns.some(y=>y.id===x.id));draft.boundaries=draft.boundaries.filter(x=>x.id!==itemId);if(boundaries.has(draft.working.sourceRevisionId))draft.working={boundary:square(),sourceRevisionId:null,carrier:null,carrierSourceRevisionId:null,weave:null};return draft;}
function cloneInfluencedEntry(entry,sourceRevision,project){const latest=entry.revisions.at(-1),working=clone(latest.working),studyId=id('weave-study');working.boundary=clone(sourceRevision.boundary);working.sourceRevisionId=sourceRevision.boundarySourceRevisionId;working.carrier=clone(sourceRevision.carrier);working.carrierSourceRevisionId=sourceRevision.id;working.weave.studyId=studyId;working.weave.sourceName=sourceRevision.name||working.weave.sourceName;working.weave.sourceContext.sourceCarrierRevisionId=sourceRevision.id;working.weave.sourceContext.snapshot=clone(sourceRevision);for(const f of influencesOf(working.weave))f.id=id('field');working.weave.derived=deriveCarrier?refreshWeave(working,project.id).weave.derived:working.weave.derived;const revision={id:id('weave-revision'),number:1,createdAt:new Date().toISOString(),parentRevisionId:null,weaveVersion:working.weave.weaveVersion||WEAVE_VERSIONS.study,working};return{id:studyId,name:uniqueName(project.weaveStudies,entry.name),latestRevisionId:revision.id,revisions:[revision]};}
export function duplicateLibraryItem(project,type,itemId){const draft=clone(project);if(type==='influenced'){const entry=draft.weaveStudies.find(x=>x.id===itemId);if(!entry)throw Error('Influenced Grid is missing.');const source=findCarrierRevision(draft,entry.revisions.at(-1).working.weave.sourceContext.sourceCarrierRevisionId)?.revision;if(!source)throw Error('Source Weave Pattern is missing.');draft.weaveStudies.push(cloneInfluencedEntry(entry,source,draft));return draft;}if(type==='pattern'){const entry=draft.carrierStudies.find(x=>x.id===itemId);if(!entry)throw Error('Weave Pattern is missing.');const source=entry.revisions.at(-1),carrier=clone(source.carrier),oldRevisionIds=new Set(entry.revisions.map(r=>r.id));carrier.id=id('carrier');const revision={...clone(source),id:id('carrier-revision'),number:1,parentRevisionId:null,createdAt:new Date().toISOString(),carrier};const pattern={id:id('carrier-study'),name:uniqueName(draft.carrierStudies,entry.name),latestRevisionId:revision.id,revisions:[revision]};revision.name=pattern.name;draft.carrierStudies.push(pattern);for(const influenced of project.weaveStudies.filter(x=>oldRevisionIds.has(x.revisions.at(-1).working.weave.sourceContext.sourceCarrierRevisionId)))draft.weaveStudies.push(cloneInfluencedEntry(influenced,revision,draft));return draft;}const entry=draft.boundaries.find(x=>x.id===itemId);if(!entry)throw Error('Boundary is missing.');const source=entry.revisions.at(-1),revision={...clone(source),id:id('revision'),number:1,parentRevisionId:null,createdAt:new Date().toISOString()},boundary={id:id('boundary'),name:uniqueName(draft.boundaries,entry.name),latestRevisionId:null,revisions:[revision]};boundary.latestRevisionId=revision.id;draft.boundaries.push(boundary);const oldIds=new Set(entry.revisions.map(r=>r.id));for(const pattern of project.carrierStudies.filter(x=>x.revisions.some(r=>oldIds.has(r.boundarySourceRevisionId)))){const latest=pattern.revisions.at(-1),carrier=clone(latest.carrier);carrier.id=id('carrier');const pr={...clone(latest),id:id('carrier-revision'),number:1,parentRevisionId:null,createdAt:new Date().toISOString(),boundary:clone(revision.boundary),boundarySourceRevisionId:revision.id,carrier},pe={id:id('carrier-study'),name:uniqueName(draft.carrierStudies,pattern.name),latestRevisionId:pr.id,revisions:[pr]};pr.name=pe.name;draft.carrierStudies.push(pe);const sourceIds=new Set(pattern.revisions.map(r=>r.id));for(const influenced of project.weaveStudies.filter(x=>sourceIds.has(x.revisions.at(-1).working.weave.sourceContext.sourceCarrierRevisionId)))draft.weaveStudies.push(cloneInfluencedEntry(influenced,pr,draft));}return draft;}

function sourceParameterization(carrier){return carrier?.kind===STITCH_SOURCE?STITCH_VERSIONS.parameterization:WEAVE_VERSIONS.parameterization;}
function validateFieldGeneration(g){return g.version===STITCH_VERSIONS.generation?validateStitchGeneration(g):validateCombinedGeneration(g);}
